from taf.internal.robot_typecasts.typecasts import time_to_seconds

from .operations import Operations


class ping:
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self._ping = Operations()

    def wait_for_ping(self, ip_addresses, non_critical_ips=None, timeout=2, remote_host_ip=None,
                      remote_host_username=None,
                      remote_host_password=None, **kwargs):
        """
        Execute single ping commands in a loop and wait until IP is pingable

        :param list ip_addresses: IP(s) to ping
        :param list | None non_critical_ips: IP(s) to wait for but won't stop the execution if failed
        :param int | str timeout: seconds method should wait for IP to start pinging - 2 by default
        :param str | None remote_host_ip: IP to be provided if ping should be proceeded from remote host
        :param str | None remote_host_username: username of remote host
        :param str | None remote_host_password: password of remote host
        :param int | str | None retry_interval: check ping every {retry_interval} seconds
        :param int | str | None successful_ping_count: ping command successes required to return from the method
        :return: ``None`` or dictionary with information about ping statuses for IP addresses from ``non_critical_ips`` list:

        .. code-block:: python

            non_critical_ips_status = {
                'pingable non_critical_ips': [...],
                'not pingable non_critical_ips': [...]
            }

        On RF level KW takes a list of ``ip_addresses`` and ``non_critical_ips`` as arguments

        Example of usage as KW:

        .. code-block:: robotframework

            ${non_critical_ips_status}=  Wait For Ping  @{ip_addresses}  @{non_critical_ips}
            ...  timeout=60  retry_interval=3  successful_ping_count=3
        """
        return self._ping.wait_for_ping(ip_addresses,
                                        non_critical_ips=non_critical_ips, timeout=time_to_seconds(timeout, round_to=0),
                                        remote_host_ip=remote_host_ip,
                                        remote_host_username=remote_host_username,
                                        remote_host_password=remote_host_password,
                                        **kwargs)

    def wait_for_no_ping(self, ip_addresses, non_critical_ips=None, timeout=2, remote_host_ip=None,
                         remote_host_username=None,
                         remote_host_password=None, **kwargs):
        """
        Execute single ping commands in a loop and wait until IP is unpingable

        :param list ip_addresses: IP(s) to ping
        :param list | None non_critical_ips: IP(s) to wait for but won't stop the execution if failed
        :param int | str timeout: seconds method should wait for IP to start pinging - 2 by default
        :param str | None remote_host_ip: IP to be provided if ping should be proceeded from remote host
        :param str | None remote_host_username: username of remote host
        :param str | None remote_host_password: password of remote host
        :param int | str | None retry_interval: check ping every {retry_interval} seconds
        :param int | str | None unsuccessful_ping_count: failures required to return from the method
        :return: ``None`` or dictionary with information about ping statuses for IP addresses from ``non_critical_ips`` list:

        .. code-block:: python

            non_critical_ips_status = {
                'pingable non_critical_ips': [...],
                'not pingable non_critical_ips': [...]
            }

        On RF level KW takes a list of ``ip_addresses`` and ``non_critical_ips`` as arguments

        Example of usage as KW:

        .. code-block:: robotframework

            ${non_critical_ips_status}=  Wait For No Ping  @{ip_addresses}  @{non_critical_ips}
            ...  timeout=60  retry_interval=3  unsuccessful_ping_count=3
        """
        return self._ping.wait_for_no_ping(ip_addresses,
                                           non_critical_ips=non_critical_ips,
                                           timeout=time_to_seconds(timeout, round_to=0),
                                           remote_host_ip=remote_host_ip,
                                           remote_host_username=remote_host_username,
                                           remote_host_password=remote_host_password,
                                           **kwargs)

    def ip_is_pingable(self, ip_address, timeout=2, remote_host_ip=None, remote_host_username=None,
                       remote_host_password=None):
        """
        Run ping and almost instantaneously return the answer

        :param str ip_address: IP to ping e.g. (127.0.0.1)
        :param int | str timeout: seconds to wait for response from host - 2 by default
        :param str | None remote_host_ip: IP to be provided if ping should be proceeded from remote host
        :param str | None remote_host_username: username of remote host
        :param str | None remote_host_password: password of remote host
        :return: ``True`` if received response from IP address ``False`` otherwise

        On RF level KW takes ``ip_address`` as argument

        Example of usage as KW:

        .. code-block:: robotframework

            ${is_pingable}=  Ip Is Pingable  127.0.0.1
            Should Be Equal  ${is_pingable}  True

        """
        return self._ping.ip_is_pingable(ip_address, timeout=time_to_seconds(timeout, round_to=0),
                                         remote_host_ip=remote_host_ip,
                                         remote_host_username=remote_host_username,
                                         remote_host_password=remote_host_password)

    def ip_is_unpingable(self, ip_address, timeout=2, remote_host_ip=None, remote_host_username=None,
                         remote_host_password=None):
        """
        Work opposite to :py:func:`ip_is_pingable` method

        :param str ip_address: IP to ping
        :param int|str timeout: seconds to wait for response from host - 2 by default
        :param str|None remote_host_ip: IP to be provided if ping should be proceeded from remote host
        :param str|None remote_host_username: username of remote host
        :param str|None remote_host_password: password of remote host
        :return: ``False`` if received response from IP address ``True`` otherwise

        On RF level KW takes ``ip_address`` as argument

        Example of usage as KW:

        .. code-block:: robotframework

            ${is_unpingable}=  Ip Is Unpingable  127.0.0.1
            Should Be Equal  ${is_unpingable}  False
        """
        return self._ping.ip_is_unpingable(ip_address, timeout=time_to_seconds(timeout, round_to=0),
                                           remote_host_ip=remote_host_ip,
                                           remote_host_username=remote_host_username,
                                           remote_host_password=remote_host_password)
